// The CPU decides what to render (C# side)
// Unity does this automatically every frame, but you can see it:
void Update()
{
    // This runs on the CPU - it decides position, rotation, scale
    transform.Rotate(0, 10 * Time.deltaTime, 0);
}

// The GPU draws the pixels (shader side)
// This HLSL code runs on the GPU for every vertex/pixel:
// float4 vert(float4 pos : POSITION) : SV_POSITION
