// This all runs during the Update stage (CPU)
void Update()
{
    // Move the player
    transform.Translate(Input.GetAxis("Horizontal") * speed * Time.deltaTime, 0, 0);

    // Animate a value
    currentHealth = Mathf.Lerp(currentHealth, targetHealth, 0.1f);

    // Change material color
    renderer.material.color = Color.Lerp(Color.red, Color.green, healthPercent);
}

// Note: None of this draws pixels yet! It just changes data.

// You can see batching in the Stats window (Game View → Stats)
// Look for 'Batches' and 'Saved by batching'

// Static batching: objects that never move
// Mark objects as 'Static' in the Inspector

// Dynamic batching: small moving objects (automatic in URP)
// GPU Instancing: same mesh + same material, different transforms

// SRP Batcher (URP): batches across different materials if shaders are the same

// In Unity, you choose your pipeline in Project Settings:
// Edit → Project Settings → Graphics → Scriptable Render Pipeline Settings

// URP Asset (recommended for new projects)
// HDRP Asset (for high-end PC/console)
// None = Built-in Render Pipeline (legacy)

// You can also switch pipelines at runtime (advanced):
// GraphicsSettings.defaultRenderPipeline = myURPAsset;

// In Built-in RP, you configure rendering in the Graphics Settings
// Edit → Project Settings → Graphics

// Built-in has two rendering paths:
// 1. Forward (default) — one pass per light per object
// 2. Deferred — stores surface data in G-buffers, then lights in screen space

// You can see the rendering path on your camera:
Camera.main.renderingPath = RenderingPath.Forward;
// or
Camera.main.renderingPath = RenderingPath.DeferredShading;

// Built-in RP rendering paths explained

// Forward Rendering:
// Object A + 3 lights = 3 draw calls for Object A
// Object B + 3 lights = 3 draw calls for Object B
// Total: 6 draw calls for lighting alone

// Deferred Rendering:
// Pass 1: Render all objects to G-buffers (color, normal, depth)
// Pass 2: Apply all lights in screen space (one pass per light, but per-pixel)
// More efficient with many lights, but uses more memory

// URP solves this with the Single Pass Forward renderer
// which handles multiple lights in one pass

// URP's Single Pass Forward (simplified concept)
// Instead of:
//   Pass 1: Object with Light 1
//   Pass 2: Object with Light 2
//   Pass 3: Object with Light 3

// URP does:
//   Pass 1: Object with Light 1 + Light 2 + Light 3 (all in one shader)

// In URP shaders, you access all lights like this:
Light mainLight = GetMainLight();           // Directional light
// Additional lights are handled automatically in the shader loop
// Unity limits additional lights per object (default: 4)

// URP Project Structure:
// Assets/Settings/UniversalRP-HighQuality.asset  ← Quality settings
// Assets/Settings/UniversalRP-LowQuality.asset   ← Different quality level
// Assets/Settings/ForwardRenderer.asset          ← Renderer configuration

// You assign the URP Asset in:
// Edit → Project Settings → Graphics → Scriptable Render Pipeline Settings

// The Renderer Asset (ForwardRenderer) controls:
// - What render passes exist (Opaque, Transparent, Post-processing)
// - Renderer Features (custom injected passes)
// - Default shader materials
